INSERT INTO `sequence` VALUES (1,1,1,1,'','Choix de la classe','Aller choisit ta classe p\'tit gars et choisit bien '),(2,1,2,1,'','fin quête initiale','Maintenant tu es prêt à vivre ton aventure, je n\'ai plus rien à te transmettre !'),(3,4,1,NULL,'','Louer une chambre','Bonjour jeune aventurier, si tu souhaites te reposer dans mon auberge, il faudra me payer d\'avance.'),(4,5,1,NULL,'','Rejoindre une guilde','Bonjour jeune aventurier, si tu es là j\'imagine que c\'est parce que tu es à la recherche de compagnon de route. \r\nJe suis la bonne personne pour cela, néanmoins il te reste quelques formalités administrative à effectuer.\r\n\r\nTu peux rechercher dans ce registre les guildes qui ont besoins de personnes comme toi ! Une fois que tu auras fait ton choix ce sera au chef de la guilde d\'accepter ta candidature !\r\n');
